<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class ScheduleItem extends Model{protected $fillable=['department_id','teacher_id','group_name','subject','room','weekday','starts_at','ends_at','sort','is_active'];protected $casts=['is_active'=>'boolean'];public function department(){return $this->belongsTo(Department::class);}public function teacher(){return $this->belongsTo(Teacher::class);}}